#!/usr/bin/env python3
"""Email V2 R2 — build the review artifact's data file and the art-direction document from territories.json."""
from __future__ import annotations

import json
from pathlib import Path

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[2]
DOC = REPO / "docs/site00/idnty/visual-authority/email-v2/r2/ART_DIRECTION_R2.md"


def main() -> None:
    data = json.loads((HERE / "territories.json").read_text())
    (HERE / "review/data.js").write_text(
        "// Generated by build_review.py from territories.json. Do not edit by hand.\n"
        f"window.R2_DATA = {json.dumps(data, indent=2, ensure_ascii=False)};\n"
    )

    out = [
        "# Email V2 R2 — art direction territories",
        "",
        "Nine graphic territories for the three benchmark emails. The copy is the approved benchmark copy, unchanged.",
        "Only the graphic art direction changes. Nothing here is approved; the founder selects one direction per email.",
        "",
        "Review: `scripts/df-email-v2-benchmark/r2/review/index.html` (email, direction, device, compare with R1, rationale).",
        "",
        "| Email | A | B | C |",
        "|---|---|---|---|",
    ]
    for e in data["emails"]:
        out.append(f"| {e['id']} · {e['name']} | " + " | ".join(t["title"] for t in e["territories"]) + " |")
    for e in data["emails"]:
        out += ["", f"## {e['id']} · {e['name']}", "", f"Job: {e['job']}", "", f"{e['r1_note']}"]
        for t in e["territories"]:
            out += [
                "",
                f"### {t['id'].replace('_', ' · ')} — {t['title']}",
                "",
                f"**Central idea.** {t['central_idea']}",
                "",
                "| Aspect | Direction |",
                "|---|---|",
                f"| Signature device | {t['signature_device']} |",
                f"| Typography | {t['typography']} |",
                f"| Image treatment | {t['image_treatment']} |",
                f"| Rhythm | {t['rhythm']} |",
                f"| Word / image | {t['word_image']} |",
                f"| Action | {t['cta']} |",
                f"| Red | {t['red_use']} |",
                f"| Email-safe build | {t['email_safe']} |",
                f"| Premium asset candidate | {t['premium_candidate']} |",
            ]
    out += [
        "",
        "## Medium",
        "",
        "Each territory is a 640px composition built from rows and fixed-width cells, so each maps to table HTML.",
        "Pictures behind live text are background-image cells (VML fill for Outlook in production).",
        "There is no JavaScript, positioning, or scroll effect, and nothing depends on web fonts (Arial Narrow fallback).",
        "The full email is never rasterized. Headlines, copy, personalization, and actions stay live HTML.",
        "Mobile layouts are authored per territory at 480px and below.",
        "",
        "## Imagery",
        "",
        "Every photograph is a new crop of the existing BATCH I plates (`df-v2-mass-cj-2026-10-11`). Drawings are code-native",
        "(`r2/prepare_r2.py`). OpenArt generations: 0. Credits: 0. Premium candidates above are proposals only.",
        "",
        "## Status",
        "",
        "FOUNDER SELECTION PENDING. Full 20-email rollout not authorized. No sending, no merge, no deploy.",
        "",
    ]
    DOC.parent.mkdir(parents=True, exist_ok=True)
    DOC.write_text("\n".join(out))
    print("wrote", HERE / "review/data.js", "and", DOC)


if __name__ == "__main__":
    main()
